                "unite":  "\u003csvg viewBox=\"0 0 260 240\"\u003e\n            \u003c!-- 中心核心 --\u003e\n            \u003ccircle class=\"center-pulse\" cx=\"130\" cy=\"120\" r=\"30\" fill=\"var(--gold)\" stroke=\"var(--ink)\" stroke-width=\"3\"/\u003e\n            \u003ccircle cx=\"130\" cy=\"120\" r=\"16\" fill=\"var(--cinnabar)\" stroke=\"var(--ink)\" stroke-width=\"2.5\"/\u003e\n            \u003ctext x=\"130\" y=\"125\" text-anchor=\"middle\" font-family=\"Georgia\" font-size=\"11\" font-weight=\"bold\" fill=\"var(--paper)\"\u003eunite\u003c/text\u003e\n\n            \u003c!-- 五个汇聚的小点 --\u003e\n            \u003cg class=\"gather-dot gd1\" style=\"--px:60px;--py:50px;\"\u003e\n              \u003ccircle cx=\"60\" cy=\"50\" r=\"10\" fill=\"var(--cinnabar)\" stroke=\"var(--ink)\" stroke-width=\"2.5\"/\u003e\n            \u003c/g\u003e\n            \u003cg class=\"gather-dot gd2\" style=\"--px:200px;--py:55px;\"\u003e\n              \u003ccircle cx=\"200\" cy=\"55\" r=\"10\" fill=\"var(--sage)\" stroke=\"var(--ink)\" stroke-width=\"2.5\"/\u003e\n            \u003c/g\u003e\n            \u003cg class=\"gather-dot gd3\" style=\"--px:55px;--py:185px;\"\u003e\n              \u003ccircle cx=\"55\" cy=\"185\" r=\"10\" fill=\"var(--indigo)\" stroke=\"var(--ink)\" stroke-width=\"2.5\"/\u003e\n            \u003c/g\u003e\n            \u003cg class=\"gather-dot gd4\" style=\"--px:205px;--py:190px;\"\u003e\n              \u003ccircle cx=\"205\" cy=\"190\" r=\"10\" fill=\"var(--plum)\" stroke=\"var(--ink)\" stroke-width=\"2.5\"/\u003e\n            \u003c/g\u003e\n            \u003cg class=\"gather-dot gd5\" style=\"--px:130px;--py:30px;\"\u003e\n              \u003ccircle cx=\"130\" cy=\"30\" r=\"10\" fill=\"var(--gold)\" stroke=\"var(--ink)\" stroke-width=\"2.5\"/\u003e\n            \u003c/g\u003e\n\n            \u003c!-- 外围小虚线环 --\u003e\n            \u003ccircle cx=\"130\" cy=\"120\" r=\"90\" fill=\"none\" stroke=\"var(--cinnabar)\" stroke-width=\"1.5\" stroke-dasharray=\"4 6\" opacity=\".35\"/\u003e\n          \u003c/svg\u003e",
                "weave":  "\u003csvg viewBox=\"0 0 180 180\"\u003e\n            \u003cpath class=\"thread t1\" d=\"M 20 20 Q 30 90 20 160\" /\u003e\n            \u003cpath class=\"thread t2\" d=\"M 60 20 Q 70 90 60 160\" /\u003e\n            \u003cpath class=\"thread t3\" d=\"M 100 20 Q 110 90 100 160\" /\u003e\n            \u003cpath class=\"thread t4\" d=\"M 140 20 Q 150 90 140 160\" /\u003e\n            \u003cpath class=\"thread t5\" d=\"M 10 60 Q 90 50 170 60\" /\u003e\n            \u003cpath class=\"thread t1\" d=\"M 10 100 Q 90 110 170 100\" /\u003e\n            \u003cpath class=\"thread t3\" d=\"M 10 140 Q 90 130 170 140\" /\u003e\n            \u003ccircle class=\"weave-pulse\" cx=\"90\" cy=\"90\" r=\"8\" fill=\"var(--turmeric)\" stroke=\"var(--ink)\" stroke-width=\"2\"/\u003e\n          \u003c/svg\u003e"
