                   "anniversary":  ".di-art[data-art=\"anniversary\"]{--paper:#FDF7EC;\n  --paper-2:#F5EBD5;\n  --ink:#2A1820;\n  --wine:#8B1E3F;\n  --wine-soft:#F5D9E0;\n  --rose:#E85A7C;\n  --rose-soft:#FBE2EA;\n  --gold:#D4A028;\n  --gold-soft:#F8EDC8;\n  --cream:#FFF3D6;\n  --plum:#5C1F3F;\n\n  --shadow-hard:7px 7px 0 var(--ink);\n  --shadow-hard-sm:4px 4px 0 var(--ink);\n  --radius-lg:28px;\n  --radius-md:20px;}\r\n.di-art[data-art=\"anniversary\"] .an-calendar-ring{\n  transform-origin:160px 120px;\n  animation:anniversary__calendarSpin 40s linear infinite;\n}\r\n.di-art[data-art=\"anniversary\"] .an-page-flip{\n  transform-origin:160px 120px;\n  animation:anniversary__pageFlip 4s ease-in-out infinite;\n}\r\n.di-art[data-art=\"anniversary\"] .an-date{\n  animation:anniversary__dateGlow 3s ease-in-out infinite;\n  transform-origin:160px 120px;\n}\r\n.di-art[data-art=\"anniversary\"] .an-flame{\n  transform-origin:160px 78px;\n  animation:anniversary__flameFlicker 0.8s ease-in-out infinite alternate;\n}\r\n.di-art[data-art=\"anniversary\"] .an-halo{\n  transform-origin:160px 120px;\n  animation:anniversary__haloBreath 3.2s ease-in-out infinite;\n}\r\n.di-art[data-art=\"anniversary\"] .an-bubbles{\n  transform-origin:160px 120px;\n  animation:anniversary__bubbleSpin 20s linear infinite;\n}\r\n.di-art[data-art=\"anniversary\"] .an-confetti{\n  animation:anniversary__confettiFall 3s ease-in infinite;\n}\r\n.di-art[data-art=\"anniversary\"] .an-confetti.c2{ animation-delay:.5s; }\r\n.di-art[data-art=\"anniversary\"] .an-confetti.c3{ animation-delay:1s; }\r\n.di-art[data-art=\"anniversary\"] .an-confetti.c4{ animation-delay:1.5s; }\r\n.di-art[data-art=\"anniversary\"] .an-confetti.c5{ animation-delay:2s; }\r\n@keyframes anniversary__calendarSpin{\n  to{ transform:rotate(360deg); }\n}\r\n@keyframes anniversary__dateGlow{\n  0%,100%{ opacity:1; transform:scale(1); }\n  50%{ opacity:.85; transform:scale(1.08); }\n}\r\n@keyframes anniversary__bubbleSpin{\n  to{ transform:rotate(360deg); }\n}\r\n@keyframes anniversary__pageFlip{\n  0%, 30%   { transform:rotateY(0deg); }\n  50%, 70%  { transform:rotateY(-180deg); }\n  90%, 100% { transform:rotateY(-360deg); }\n}\r\n@keyframes anniversary__haloBreath{\n  0%,100%{ opacity:.4; transform:scale(.95); }\n  50%{ opacity:.75; transform:scale(1.08); }\n}\r\n@keyframes anniversary__confettiFall{\n  0%{ opacity:0; transform:translateY(-30px) rotate(0); }\n  20%{ opacity:1; }\n  80%{ opacity:.85; }\n  100%{ opacity:0; transform:translateY(200px) rotate(360deg); }\n}\r\n@keyframes anniversary__flameFlicker{\n  0%{ transform:scale(1) rotate(-3deg); opacity:1; }\n  100%{ transform:scale(1.1) rotate(3deg); opacity:.85; }\n}",
